/// The pattern predicates still checked when a function is selected.
pub fn pattern_predicate<C: PatternContext>(ctx: &C, id: u16) -> bool {
    match id {
        _ => unreachable!("pattern predicate {id} is not in this table"),
    }
}

/// The node predicates the table checks.
pub fn node_predicate<D: Dag, H: Hooks<D>>(dag: &D, hooks: &H, value: SDValue, id: u16) -> bool {
    let args = (dag, hooks, value);
    match id {
        0 => predicates::unindexed_store(args),
        1 => predicates::non_truncating_store(args),
        2 => predicates::non_extending_load(args),
        3 => predicates::mx_loadi16(args),
        4 => predicates::mx_loadi32(args),
        5 => predicates::unindexed_load(args),
        6 => predicates::memory_vt_i8(args),
        7 => predicates::mx_imm_1to8(args),
        8 => predicates::memory_vt_i16(args),
        9 => predicates::mx_store_load_safe(args),
        10 => predicates::sext_load(args),
        11 => predicates::zext_load(args),
        12 => predicates::ext_load(args),
        13 => predicates::memory_vt_i32(args),
        _ => unreachable!("node predicate {id} is not in this table"),
    }
}

